var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"FortunasFruitsAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		    var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.erh.plz!=undefined){
			
			if(gameController.rqk!=parseInt(tmpMess[1])){
				
			gameController.slf=parseInt(tmpMess[1]);	
			gameController.rqk=parseInt(tmpMess[1]);	
			gameController.erh.plz.crn("creditd", "#emk", [gameController.vpn(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
